//! hid.library's functions: a keyboard's or a mouse's report descriptor
//! read, and each of its reports made into keys, moves and buttons for
//! keyboard.device and mouse.device (sdk.hid). Open it with
//! OpenLibrary("hid.library", 1).
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/hid_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const utility = @import("../libs/utility/utility.zig");
const hid = @import("../libs/hid/hid.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "hid.library";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const OpenHID = libraries.lvo(4);
    pub const CloseHID = libraries.lvo(5);
    pub const HIDInput = libraries.lvo(6);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OpenHID = *const fn (*HIDBase, ?[*]const u8, u32, ?[*]const utility.TagItem) callconv(.c) ?*hid.HIDFunction;
    pub const CloseHID = *const fn (*HIDBase, ?*hid.HIDFunction) callconv(.c) void;
    pub const HIDInput = *const fn (*HIDBase, *hid.HIDFunction, [*]const u8, u32) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const HIDBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *HIDBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// A function for a device by its report descriptor: the sources of what it describes opened; null where it describes nothing the library drives.
    pub fn OpenHID(self: *HIDBase, descriptor: ?[*]const u8, length: u32, tags: ?[*]const utility.TagItem) ?*hid.HIDFunction {
        return libraries.call(self, LVO.OpenHID, Fn.OpenHID, .{ descriptor, length, tags });
    }

    /// A function closed: its sources let go of what the device held, and closed. Null does nothing.
    pub fn CloseHID(self: *HIDBase, function: ?*hid.HIDFunction) void {
        return libraries.call(self, LVO.CloseHID, Fn.CloseHID, .{function});
    }

    /// One input report, as the descriptor lays it out, made into events for the sources.
    pub fn HIDInput(self: *HIDBase, function: *hid.HIDFunction, report: [*]const u8, length: u32) void {
        return libraries.call(self, LVO.HIDInput, Fn.HIDInput, .{ function, report, length });
    }
};
